import type { Bounds, Vec2 } from '../geometry/types'

/**
 * Level JSON in `public/levels/`, generated by `npm run levels` (`scripts/import-ipe.ts`) from the
 * Unity level files in `legacy/levels/` and the new level sources in `levels/`.
 *
 * Coordinates use the SVG convention (y points down). IPE levels are centred on the origin and scaled
 * so the larger side of the bounding box has the size the Unity version used for that game
 * ({@link LEVEL_SIZE}); the five Unity `.asset` levels were made by hand in those units and are only
 * mirrored (y flipped), not scaled.
 */
export const LEVEL_FORMAT_VERSION = 1

export type Collection =
  | 'art-gallery'
  | 'kings-taxes/mst'
  | 'kings-taxes/spanner'
  | 'kings-taxes/tsp'
  | 'divide'
  | 'convex-hull'
  | 'voronoi'
  | 'lawn-mowing'
  | 'roads/steiner'
  | 'roads/bichromatic'

export const COLLECTIONS: readonly Collection[] = [
  'art-gallery',
  'kings-taxes/mst',
  'kings-taxes/spanner',
  'kings-taxes/tsp',
  'divide',
  'convex-hull',
  'voronoi',
  'lawn-mowing',
  'roads/steiner',
  'roads/bichromatic',
]

/** Larger side of the bounding box of an imported IPE level, per collection (as in Unity). */
export const LEVEL_SIZE: Record<Collection, number> = {
  'art-gallery': 9,
  'kings-taxes/mst': 6,
  'kings-taxes/spanner': 6,
  'kings-taxes/tsp': 6,
  divide: 5,
  'convex-hull': 6,
  voronoi: 16,
  'lawn-mowing': 1,
  'roads/steiner': 6,
  'roads/bichromatic': 6,
}

interface LevelBase {
  /** `<collection>/<name>`, also the path of the file below `public/levels/` without `.json`. */
  id: string
  collection: Collection
  /** File name without extension, e.g. `agLevel4_8`. */
  name: string
  /** Level number from the file name (the Unity scene order). */
  number: number
  /** Source file, relative to the repository root. */
  source: string
  bounds: Bounds
}

/**
 * Art gallery ("Licht ins Verlies"). The outer boundary has positive signed area (shoelace formula on
 * the stored coordinates, so it runs clockwise on screen), holes negative. Rings are not closed (the
 * last vertex is not repeated).
 */
export interface ArtGalleryLevel extends LevelBase {
  collection: 'art-gallery'
  /** Number of torches the level designer allowed (k); not a proven minimum. */
  torches: number
  outer: Vec2[]
  holes: Vec2[][]
}

/** Kings Taxes (MST, t-spanner, TSP): settlements; villages and castles differ only in look. */
export interface KingsTaxesLevel extends LevelBase {
  collection: 'kings-taxes/mst' | 'kings-taxes/spanner' | 'kings-taxes/tsp'
  /** Spanner ratio t (spanner levels only). */
  ratio?: number
  villages: Vec2[]
  castles: Vec2[]
}

/** Divide (ham sandwich): three kinds of soldiers, each with an even count. */
export interface DivideLevel extends LevelBase {
  collection: 'divide'
  /** Allowed swaps. */
  swaps: number
  spearmen: Vec2[]
  archers: Vec2[]
  mages: Vec2[]
}

/** Convex hull tutorial levels. */
export interface ConvexHullLevel extends LevelBase {
  collection: 'convex-hull'
  points: Vec2[]
}

/**
 * "Erobere das Land" (Voronoi game): a map with land and water, from `levels/voronoi/*.ipe`. `bounds` is
 * the map sheet (the frame, larger side 16); castles' cells are clipped to it. Rings are not closed;
 * outer rings have positive signed area, holes negative.
 */
export interface VoronoiLevel extends LevelBase {
  collection: 'voronoi'
  /** The land that scores: frame ∩ land − water. Several parts (islands, river banks) and lakes as holes. */
  land: Vec2[][]
  /** Water inside the outline of the land (lakes, rivers), for drawing; the sea is the rest of the sheet. */
  water: Vec2[][]
  /** Cities and gold mines: bonus points for the owner of the cell that contains them. */
  cities: Vec2[]
  mines: Vec2[]
  /** Decoration only. */
  forests: Vec2[]
  mountains: Vec2[]
}

/** The best known tours of a lawn for one number of cutters, as corner points (pyutils27 `tours`). */
export interface LawnSolution {
  tours: Vec2[][]
  /** The longest tour: the objective, and the target shown in the game. */
  maxTourLength: number
  /** Solution file, relative to the repository root. */
  source: string
  /** Who or what computed it (the solution's `meta`, e.g. the algorithm), if given. */
  meta?: Record<string, unknown>
}

/**
 * "Rasenmähen" (CG:SHOP 2027 lawn mowing), from the pyutils27 instances in `levels/lawn-mowing/`. Unlike
 * the other levels it keeps the competition's integer coordinates with y pointing UP (cell (x, y) is the
 * square [x, x + 1] × [y, y + 1]); the game flips y to draw. `bounds` is the region's bounding box.
 */
export interface LawnMowingLevel extends LevelBase {
  collection: 'lawn-mowing'
  /** Outer boundary (counterclockwise) and holes (clockwise), as in pyutils27. */
  outer: Vec2[]
  holes: Vec2[][]
  /** The cutter polyomino and its reference lattice point (`cutter`, `cutter_center`). */
  cutter: Vec2[]
  cutterCenter: Vec2
  /** The instances of this lawn by number of cutters, with the best known solution once available. */
  variants: { cutters: number; uid: string; solution?: LawnSolution }[]
  /** A real CG:SHOP instance for the theory view, not a booth lawn. */
  competition?: boolean
}

/**
 * A road network of a "Straßenbau" level: roads between nodes, which are the places (villages, then
 * castles) and, for junctions, the nodes after them.
 */
export interface RoadsNetwork {
  roads: [number, number][]
  length: number
}

/**
 * "Kreuzungen" ("Straßenbau" with junctions: the Euclidean Steiner tree), from `levels/roads/steiner/`, made
 * for this edition. Same units as the Kings Taxes levels (about 6 × 4); castles only look different.
 */
export interface RoadsSteinerLevel extends LevelBase {
  collection: 'roads/steiner'
  villages: Vec2[]
  castles: Vec2[]
  /** The Steiner minimal tree, computed offline (exact): its junctions are the nodes after the places. */
  optimum: RoadsNetwork & { junctions: Vec2[] }
  /** The shortest network without junctions (a minimum spanning tree). */
  mstLength: number
  /** How the optimum was computed. */
  method: string
}

/**
 * "Zwei Sorten" (the minimum plane bichromatic spanning tree: every road joins a castle and a village, no
 * two roads cross), from `levels/roads/bichromatic/`, made for this edition.
 */
export interface RoadsBichromaticLevel extends LevelBase {
  collection: 'roads/bichromatic'
  villages: Vec2[]
  castles: Vec2[]
  /** The shortest crossing-free castle–village network, computed offline (exact). */
  optimum: RoadsNetwork
  /** The shortest castle–village network without the crossing rule (Kruskal) and its crossings. */
  free: RoadsNetwork & { crossings: number }
  /** The greedy strategy's network (shortest allowed road that crosses none, again and again). */
  greedy: RoadsNetwork & { stuck: boolean }
  method: string
}

export type Level =
  | ArtGalleryLevel
  | KingsTaxesLevel
  | DivideLevel
  | ConvexHullLevel
  | VoronoiLevel
  | LawnMowingLevel
  | RoadsSteinerLevel
  | RoadsBichromaticLevel

/** `public/levels/index.json`: level ids per collection, in the Unity scene order. */
export interface LevelIndex {
  version: typeof LEVEL_FORMAT_VERSION
  collections: Record<Collection, string[]>
}
